 , 'kunjungan_toko' => "CREATE TABLE IF NOT EXISTS kunjungan_toko (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pengunjung_hash CHAR(64) NOT NULL, tanggal DATE NOT NULL, dibuat_pada TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unik_harian(pengunjung_hash,tanggal), INDEX(tanggal)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];
