 $number=trim($_GET['order']??''); $phone=preg_replace('/\D/','',$_GET['phone']??''); if($number===''||strlen($phone)<8) serviceReply(false,'Masukkan nomor pesanan dan nomor telepon pemesan.',[],422);
 $stmt=$conn->prepare('SELECT nomor_pesanan,nama_penerima,tanggal_pengiriman,metode_pengiriman,status_pesanan,status_pembayaran,nama_kurir,telepon_kurir,catatan_pengiriman,dibuat_pada FROM pesanan_web WHERE nomor_pesanan=? AND REPLACE(REPLACE(REPLACE(telepon,"+",""),"-","")," ","") LIKE ? LIMIT 1'); $like='%'.$phone; $stmt->bind_param('ss',$number,$like); $stmt->execute(); $row=$stmt->get_result()->fetch_assoc(); $stmt->close(); if(!$row) serviceReply(false,'Pesanan tidak ditemukan. Periksa kembali nomor pesanan dan telepon.',[],404); serviceReply(true,'Status pesanan ditemukan.',['order'=>$row]);
