if ($_SERVER['REQUEST_METHOD']==='GET' && $action==='reviews') { $result=$conn->query("SELECT nama,rating,isi,dibuat_pada FROM ulasan_pelanggan WHERE status='Tampil' ORDER BY id DESC LIMIT 30"); serviceReply(true,'Ulasan pelanggan.',['reviews'=>$result->fetch_all(MYSQLI_ASSOC)]); }
