if ($_SERVER['REQUEST_METHOD']==='GET' && $action==='blog') { $result=$conn->query("SELECT id,judul,ringkasan,isi,dibuat_pada FROM artikel_blog WHERE status='Terbit' ORDER BY id DESC LIMIT 30"); serviceReply(true,'Artikel toko.',['articles'=>$result->fetch_all(MYSQLI_ASSOC)]); }
