if ($_SERVER['REQUEST_METHOD']==='GET' && $action==='admin') { if(!$admin) serviceReply(false,'Hanya admin.',[],403); $returns=$conn->query('SELECT r.*,o.nomor_pesanan,a.nama AS nama_pelanggan FROM permintaan_layanan r JOIN pesanan_web o ON o.id_pesanan=r.id_pesanan JOIN akun_pengguna a ON a.id_akun=r.id_akun ORDER BY r.id DESC')->fetch_all(MYSQLI_ASSOC); $reviews=$conn->query('SELECT * FROM ulasan_pelanggan ORDER BY id DESC')->fetch_all(MYSQLI_ASSOC); $articles=$conn->query('SELECT * FROM artikel_blog ORDER BY id DESC')->fetch_all(MYSQLI_ASSOC);$messages=$conn->query('SELECT * FROM pesan_kontak ORDER BY id DESC LIMIT 100')->fetch_all(MYSQLI_ASSOC); $settings=[]; $rs=$conn->query('SELECT kunci,nilai FROM pengaturan_toko'); while($r=$rs->fetch_assoc())$settings[$r['kunci']]=$r['nilai'];$visitors=(int)$conn->query("SELECT COUNT(*) n FROM kunjungan_toko WHERE tanggal=CURDATE()")->fetch_assoc()['n'];$sales=0;$top=[];$ordersTable=$conn->query("SHOW TABLES LIKE 'pesanan_web'");if($ordersTable&&$ordersTable->num_rows){$paid=$conn->query("SELECT COALESCE(SUM(total),0) total FROM pesanan_web WHERE status_pembayaran='Lunas'")->fetch_assoc();$sales=(float)$paid['total'];$or=$conn->query("SELECT items_json FROM pesanan_web WHERE status_pembayaran='Lunas'");while($row=$or->fetch_assoc()){foreach((json_decode($row['items_json'],true)?:[]) as $item){$n=$item['nama']??'Produk';$top[$n]=($top[$n]??0)+(int)($item['jumlah']??1);}}}arsort($top);$best=$top?array_key_first($top):'Belum ada penjualan';serviceReply(true,'Data layanan admin.',['returns'=>$returns,'reviews'=>$reviews,'articles'=>$articles,'messages'=>$messages,'settings'=>$settings,'analytics'=>['pengunjung_hari_ini'=>$visitors,'penjualan_lunas'=>$sales,'produk_terlaris'=>$best,'terjual'=>$top[$best]??0]]); }
if ($_SERVER['REQUEST_METHOD']!=='POST') serviceReply(false,'Metode tidak didukung.',[],405);
if ($action==='contact') { $name=trim($body['nama']??'');$email=trim($body['email']??'');$message=trim($body['pesan']??''); if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($message)<10)serviceReply(false,'Lengkapi nama, email valid, dan pesan minimal 10 karakter.',[],422);$s=$conn->prepare('INSERT INTO pesan_kontak(nama,email,pesan) VALUES(?,?,?)');$s->bind_param('sss',$name,$email,$message);if(!$s->execute())serviceReply(false,'Pesan gagal disimpan.',[],500);serviceReply(true,'Pesan berhasil dikirim. Admin akan menindaklanjuti.'); }
