if($action==='return_request') { if(($user['peran']??'')!=='pelanggan')serviceReply(false,'Fitur ini hanya untuk pelanggan.',[],403);$id=(int)($body['id_pesanan']??0);$type=$body['jenis']??'';$reason=trim($body['alasan']??'');if(!in_array($type,['Pengembalian','Penukaran'],true)||strlen($reason)<10)serviceReply(false,'Pilih pengembalian/penukaran dan isi alasan minimal 10 karakter.',[],422);$s=$conn->prepare("SELECT status_pesanan FROM pesanan_web WHERE id_pesanan=? AND id_akun=?");$s->bind_param('ii',$id,$user['id_akun']);$s->execute();$order=$s->get_result()->fetch_assoc();$s->close();if(!$order||$order['status_pesanan']!=='Selesai')serviceReply(false,'Permintaan hanya dapat dibuat untuk pesanan yang sudah selesai.',[],409);$s=$conn->prepare('INSERT INTO permintaan_layanan(id_akun,id_pesanan,jenis,alasan) VALUES(?,?,?,?)');$s->bind_param('iiss',$user['id_akun'],$id,$type,$reason);if(!$s->execute())serviceReply(false,'Permintaan gagal disimpan.',[],500);serviceReply(true,'Permintaan berhasil dikirim ke admin.'); }
if($action==='review') { if(($user['peran']??'')!=='pelanggan')serviceReply(false,'Silakan masuk sebagai pelanggan.',[],403);$rating=(int)($body['rating']??0);$content=trim($body['isi']??'');if($rating<1||$rating>5||strlen($content)<10)serviceReply(false,'Pilih rating 1–5 dan tulis ulasan minimal 10 karakter.',[],422);$s=$conn->prepare("INSERT INTO ulasan_pelanggan(id_akun,nama,rating,isi,status) VALUES(?,?,?,?,'Menunggu')");$s->bind_param('isis',$user['id_akun'],$user['nama'],$rating,$content);if(!$s->execute())serviceReply(false,'Ulasan gagal dikirim.',[],500);serviceReply(true,'Ulasan dikirim dan menunggu moderasi admin.'); }
