if($action==='setting_update') { foreach(($body['settings']??[]) as $key=>$value){if(!array_key_exists($key,$defaults))continue;$value=$key==='metode_pembayaran'?'QRIS / E-Wallet,COD':trim((string)$value);$s=$conn->prepare('INSERT INTO pengaturan_toko(kunci,nilai) VALUES(?,?) ON DUPLICATE KEY UPDATE nilai=VALUES(nilai)');$s->bind_param('ss',$key,$value);$s->execute();}serviceReply(true,'Pengaturan toko disimpan.'); }
if($action==='article_save') { $id=(int)($body['id']??0);$title=trim($body['judul']??'');$summary=trim($body['ringkasan']??'');$content=trim($body['isi']??'');$status=$body['status']??'Draft';if($title===''||$summary===''||$content===''||!in_array($status,['Draft','Terbit'],true))serviceReply(false,'Lengkapi judul, ringkasan, isi, dan status.',[],422);if($id){$s=$conn->prepare('UPDATE artikel_blog SET judul=?,ringkasan=?,isi=?,status=? WHERE id=?');$s->bind_param('ssssi',$title,$summary,$content,$status,$id);}else{$s=$conn->prepare('INSERT INTO artikel_blog(judul,ringkasan,isi,status) VALUES(?,?,?,?)');$s->bind_param('ssss',$title,$summary,$content,$status);}if(!$s->execute())serviceReply(false,'Artikel gagal disimpan.',[],500);serviceReply(true,'Artikel disimpan.'); }
